{"l":6938,"g":7,"b":5,"cefr":"B1","role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket ord passer: 'I'm not ___ getting up so early.'","o":["use to","using to","usual to","used to"],"a":"used to","r":"'Be used to' + ing-form betyder at være vant til noget."},
{"l":6942,"g":7,"b":5,"cefr":"B1","role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket ord passer: 'The old tree, ___ is over two hundred years old, fell down in the storm.'","o":["which","who","that","whose"],"a":"which","r":"Om ting bruger man 'which'. 'That' kan ikke bruges, når der står komma om sætningen."},
{"l":6948,"g":7,"b":5,"cefr":"B1","role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvilket ord betyder næsten det samme som 'clever' i 'a clever idea'?","o":["boring","bright","brief","bitter"],"a":"bright","r":"'A bright idea' er en god og klog idé, ligesom 'a clever idea'."},
{"l":6962,"g":7,"b":5,"cefr":"B1","role":"challenge","insight":"reframing","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'deltage i' på engelsk i '___ a meeting'?","o":["arrange","cancel","attend","record"],"a":"attend","r":"'Attend' betyder at deltage i noget. Det betyder ikke 'vente'."},
{"l":6974,"g":7,"b":5,"cefr":"B1","role":"challenge","insight":"reframing","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'ret / temmelig' på engelsk i 'It's ___ cold today'?","o":["still","never","hardly","pretty"],"a":"pretty","r":"'Pretty' kan betyde temmelig foran et tillægsord."},
{"l":6999,"g":7,"b":5,"cefr":"B1","role":"challenge","insight":"reframing","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'bortset fra' på engelsk i '___ Tom, everyone came'?","o":["apart from","thanks to","along with","because of"],"a":"apart from","r":"'Apart from' = bortset fra."},
{"l":7000,"g":7,"b":5,"cefr":"B1","role":"challenge","insight":"reframing","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'alligevel' på engelsk i 'It was raining, but we went ___'?","o":["instead","anyway","inside","away"],"a":"anyway","r":"'Anyway' = alligevel."},
{"l":7010,"g":7,"b":5,"cefr":"B2","role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'When the power went out, Grandma simply lit some candles and told us stories until the lights came back.' Hvordan reagerede bedstemor?","o":["Hun gik i panik","Hun ringede efter hjælp","Hun tog det roligt","Hun gik straks i seng"],"a":"Hun tog det roligt","r":"'Simply' viser, at hun bare tændte stearinlys og fortalte historier. Hun tog det roligt."},
{"l":7025,"g":7,"b":5,"cefr":"B2","role":"challenge","insight":"reframing","k":"h","variant":"authored","q":"Hvad siger man på engelsk, når man vil foreslå at holde en kort pause?","o":["Shall we hold a short break?","Shall we break up for a while?","Shall we take a short brake?","Shall we take a short break?"],"a":"Shall we take a short break?","r":"Man siger 'take a break'. 'Break up' betyder slå op, og 'brake' er en bremse."},
{"l":7035,"g":7,"b":5,"cefr":"B2","role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvilket ord betyder næsten det samme som 'weird' i 'a weird noise'?","o":["strange","weak","loud","wild"],"a":"strange","r":"'Weird' betyder underlig, ligesom 'strange'."},
{"l":7055,"g":7,"b":5,"cefr":"B2","role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvilket ord passer: 'The doctor gave him some ___ about healthy eating.'","o":["advise","advice","advices","advising"],"a":"advice","r":"'Advice' er navneordet (råd) og har ikke flertal. 'Advise' er udsagnsordet."},
{"l":7070,"g":7,"b":5,"cefr":"B2","role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvilket ord passer: 'We ran ___ of milk, so I went to the shop.'","o":["off","away","out","down"],"a":"out","r":"'Run out of' betyder løbe tør for. 'Run away' betyder løbe væk."},
{"l":7090,"g":7,"b":5,"cefr":"B2","role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvilket ord betyder næsten det samme som 'essential' i 'essential equipment'?","o":["optional","practical","additional","necessary"],"a":"necessary","r":"'Essential' betyder helt nødvendig, ligesom 'necessary'. 'Optional' betyder valgfri og er næsten det modsatte."},
{"l":7110,"g":7,"b":5,"cefr":"B2","role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Most of the plastic in the ocean does not come from ships, as many believe, but from rivers carrying rubbish from cities.' Hvad tror mange forkert ifølge teksten?","o":["At plastikken kommer fra skibe","At floderne er helt rene","At byerne ikke har affald","At havet er uden plastik"],"a":"At plastikken kommer fra skibe","r":"'As many believe' viser, hvad mange tror: at plastikken kommer fra skibe. Det meste kommer fra floder."},
{"l":7130,"g":7,"b":5,"cefr":"B2","role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket ord passer: 'I'm going to ___ my bike repaired this weekend.'","o":["make","get","do","take"],"a":"get","r":"'Get something done' betyder at få nogen til at gøre noget for en, her at få cyklen repareret."},
{"l":7155,"g":8,"b":1,"cefr":"B2","role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket ord passer: 'She ___ her hair cut every six weeks.'","o":["makes","does","has","is"],"a":"has","r":"'Have something done' betyder at få det gjort af en anden. Her: hun får klippet håret."},
{"l":7175,"g":8,"b":1,"cefr":"B2","role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvilket ord passer: 'We were ___ to hear that the museum was closed.'","o":["disappointing","disappointment","disappoint","disappointed"],"a":"disappointed","r":"Vi føler skuffelsen, så det er '-ed'-formen: 'disappointed'."},
{"l":7190,"g":8,"b":1,"cefr":"B2","role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket ord passer: 'This castle ___ in the twelfth century.'","o":["was built","built","has built","was building"],"a":"was built","r":"Borgen byggede ikke noget selv, den blev bygget. Passiv i datid: 'was built'."},
{"l":7215,"g":8,"b":1,"cefr":"B2","role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'When the teacher announced a surprise test, the whole class groaned, except Ida, who just smiled.' Hvad kan man slutte om Ida?","o":["Hun var ked af det","Hun var godt forberedt","Hun havde glemt sine bøger","Hun var syg den dag"],"a":"Hun var godt forberedt","r":"Alle andre stønnede, men Ida smilede. Hun var nok ikke bekymret for prøven."},
{"l":7240,"g":8,"b":1,"cefr":"B2","role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket ord passer: 'I wish I ___ speak Spanish; the holiday would be much easier.'","o":["can","will","could","might"],"a":"could","r":"'I wish' om nutiden kræver datid, og datid af 'can' er 'could'."},
{"l":7260,"g":8,"b":1,"cefr":"B2","role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket ord passer: 'The bridge ___ next year, so the road will be closed.'","o":["will repair","is repairing","has repaired","will be repaired"],"a":"will be repaired","r":"Broen reparerer ikke selv, den bliver repareret. Derfor passiv i fremtid: 'will be repaired'."},
{"l":7280,"g":8,"b":1,"cefr":"B2","role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket ord passer: 'You can borrow my laptop ___ you promise to be careful with it.'","o":["as long as","as well as","in case","so that"],"a":"as long as","r":"'As long as' betyder så længe eller forudsat at. 'As well as' betyder såvel som."},
{"l":7310,"g":8,"b":1,"cefr":"B2","role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket ord passer: 'My phone ___ while I was swimming.'","o":["stole","was stolen","has stolen","was stealing"],"a":"was stolen","r":"Telefonen stjal ikke noget, den blev stjålet. Passiv i datid: 'was stolen'."},
{"l":7340,"g":8,"b":1,"cefr":"B2","role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad hedder 'frist' på engelsk?","o":["headline","timeline","deadline","guideline"],"a":"deadline","r":"En frist hedder 'deadline'. 'Headline' er en overskrift, og 'guideline' er en retningslinje."},
{"l":7360,"g":8,"b":1,"cefr":"B2","role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket ord passer: 'More than a thousand books ___ to the school library last year.'","o":["donated","have donated","were donating","were donated"],"a":"were donated","r":"Bøgerne blev givet af nogen, så det er passiv i datid: 'were donated'."},
{"l":7380,"g":8,"b":1,"cefr":"B2","role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket ord passer: 'I ___ my keys at school; they're not in my bag.'","o":["must have left","must leave","should leave","can't have left"],"a":"must have left","r":"'Must have left' udtrykker en sikker slutning om fortiden. Nøglerne er ikke i tasken."},
{"l":7400,"g":8,"b":1,"cefr":"B2","role":"challenge","insight":"reframing","k":"h","variant":"authored","q":"Hvad siger man på engelsk, når man vil undskylde, at nogen har måttet vente på en?","o":["Sorry that you waited me.","Sorry to keep you waiting.","Sorry, I waited for you.","Sorry, wait for me, please."],"a":"Sorry to keep you waiting.","r":"'Sorry to keep you waiting' er den faste høflige vending. 'Wait me' mangler 'for'."},
{"l":7430,"g":8,"b":2,"cefr":"B2","role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad betyder 'awkward' i 'There was an awkward silence after his joke'?","o":["lang","glad","pinlig","rolig"],"a":"pinlig","r":"'Awkward' betyder akavet eller pinlig. Ingen grinede, så stilheden blev pinlig."},
{"l":7460,"g":8,"b":2,"cefr":"B2","role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvilket ord passer: 'Mobile phones are ___ during the exam.'","o":["forbid","forbade","forbidding","forbidden"],"a":"forbidden","r":"Passiv kræver kort tillægsform: 'are forbidden' (er forbudt)."},
{"l":7470,"g":8,"b":2,"cefr":"B2","role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvilket ord passer: 'You should ___ advantage of the sunny weather and go for a walk.'","o":["take","make","get","have"],"a":"take","r":"Den faste forbindelse er 'take advantage of', altså udnytte."},
{"l":7510,"g":8,"b":2,"cefr":"B2","role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'The recipe said the bread would rise in an hour. Three hours later, it looked exactly the same.' Hvad var problemet?","o":["Brødet blev brændt","Brødet hævede ikke","Opskriften var for kort","Ovnen var for varm"],"a":"Brødet hævede ikke","r":"Brødet skulle hæve på en time, men så ens ud efter tre timer. Det hævede altså ikke."}
]$$::jsonb) AS e
JOIN (VALUES
  ('o', 'ordforråd', 'recall', 'factual', 'surface_association'),
  ('h', 'hverdagsudtryk', 'comprehension', 'conceptual', 'surface_association'),
  ('g', 'grammatik', 'application', 'applied', 'overgeneralization'),
  ('l', 'læseforståelse', 'analysis', 'inferential', 'surface_association')
) AS m(k, concept, skill, dtype, mis) ON m.k = e->>'k';
